// Pure code, no model call: the marked block of `.gitignore` and `.ignore`, which lines it holds, the edits that write it, and the text a person sees before a yes. A line outside the markers is never changed, moved, or dropped.

import { detectFamilies, globOf, type Listing } from "./starter";
import { FAMILIES, type Family } from "./starter-families";

export const BLOCK_START =
	"# >>> claudetto: generated by /claudetto:setup, edit outside this block";
export const BLOCK_END = "# <<< claudetto";

const LEADING_BANG = /^!/u;
const LEADING_SLASH = /^\//u;
const TRAILING_NEWLINE = /\n$/u;

/** The path a line names, with a negation and a leading slash removed; `undefined` for a comment or a blank. A trailing slash stays: `dir/` matches a folder only, and `dir` also matches a link to one. */
const pathOf = (line: string): string | undefined => {
	const text = line.trim();
	if (text === "" || text.startsWith("#")) {
		return undefined;
	}
	return text.replace(LEADING_BANG, "").replace(LEADING_SLASH, "");
};

/** A line `dir` also names `dir/`, so a block line `dir/` after it is redundant. */
const namedBy = (lines: readonly string[]): Set<string> => {
	const named = new Set<string>();
	for (const line of lines) {
		const path = pathOf(line);
		if (path !== undefined) {
			named.add(path);
			named.add(`${path}/`);
		}
	}
	return named;
};

const appended = (text: string, block: readonly string[]): string => {
	const tail = block.join("\n");
	if (text === "") {
		return `${tail}\n`;
	}
	const ended = text.endsWith("\n") ? text : `${text}\n`;
	const gap = ended === "\n" || ended.endsWith("\n\n") ? "" : "\n";
	return `${ended}${gap}${tail}\n`;
};

/**
 * The file with its block set to `lines`, less any path the lines outside the block already name, because the last matching
 * line wins and an appended line would undo a negation. A file with no block gets one after a blank line; an unclosed block is
 * left alone, since its end is unknown.
 */
const applyLf = (
	current: string | undefined,
	lines: readonly string[],
): string | undefined => {
	const text = current ?? "";
	const parts = text.split("\n");
	const start = parts.indexOf(BLOCK_START);
	const end = start === -1 ? -1 : parts.indexOf(BLOCK_END, start + 1);
	if (start !== -1 && end < 0) {
		return current;
	}
	const outside =
		start === -1 ? parts : [...parts.slice(0, start), ...parts.slice(end + 1)];
	const named = namedBy(outside);
	const kept = [
		...new Set(lines.filter((line) => !named.has(pathOf(line) ?? line))),
	];
	const block = [BLOCK_START, ...kept, BLOCK_END];
	if (start !== -1) {
		return [...parts.slice(0, start), ...block, ...parts.slice(end + 1)].join(
			"\n",
		);
	}
	return kept.length === 0 ? current : appended(text, block);
};

/** A CRLF file is read and written in CRLF, so its markers are found again on a rerun. */
export const applyBlock = (
	current: string | undefined,
	lines: readonly string[],
): string | undefined =>
	current?.includes("\r\n") === true
		? applyLf(current.replaceAll("\r\n", "\n"), lines)?.replaceAll("\n", "\r\n")
		: applyLf(current, lines);

const linesOfText = (text: string | undefined): string[] =>
	text === undefined || text === ""
		? []
		: text.replace(TRAILING_NEWLINE, "").split("\n");

/** The lines that differ, as `-` and `+` under a header; empty when nothing changes. */
export const diffOf = (
	path: string,
	before: string | undefined,
	after: string,
): string => {
	if (before === after) {
		return "";
	}
	const old = linesOfText(before);
	const next = linesOfText(after);
	let head = 0;
	while (head < old.length && head < next.length && old[head] === next[head]) {
		head++;
	}
	let tail = 0;
	while (
		tail < old.length - head &&
		tail < next.length - head &&
		old[old.length - 1 - tail] === next[next.length - 1 - tail]
	) {
		tail++;
	}
	return [
		`+++ ${path}`,
		...old.slice(head, old.length - tail).map((line) => `-${line}`),
		...next.slice(head, next.length - tail).map((line) => `+${line}`),
	].join("\n");
};

/** The paths `Grep` leaves out. `.ignore` has no fixed line: only a family adds to it. */
export const GITIGNORE_FIXED: readonly string[] = [
	".DS_Store",
	"Thumbs.db",
	"*.swp",
	".claude/settings.local.json",
	".claude/worktrees/",
	".claude/claudetto/",
	"CLAUDE.local.md",
];

interface IgnoreLines {
	readonly gitignore: readonly string[];
	readonly ignore: readonly string[];
}

/** A pattern names a `dir/` anywhere, or a file name, with `*` for any run of characters. */
const regexOf = (pattern: string): RegExp =>
	pattern.endsWith("/")
		? new RegExp(`(^|/)${globOf(pattern.slice(0, -1))}/`, "u")
		: new RegExp(`(^|/)${globOf(pattern)}$`, "u");

const seen = (pattern: string, paths: readonly string[]): boolean => {
	const found = regexOf(pattern);
	return paths.some((path) => found.test(path));
};

const unique = (lines: readonly string[]): string[] => [...new Set(lines)];

const DEPENDENCY_FOLDERS = new Set(
	FAMILIES.flatMap((family) => family.deps ?? []),
);

/** The names, without a trailing slash, of the root folders git ignores that a worktree can link instead of rebuild. */
export const dependencyFolders = (
	ignoredDirectories: readonly string[],
): string[] =>
	ignoredDirectories
		.filter((path) => DEPENDENCY_FOLDERS.has(path))
		.map((path) => path.slice(0, -1));

/**
 * A heavy path git tracks is searched but not worth listing, so it goes to `.ignore`; one git does not track goes to
 * `.gitignore`. A lock or minified file is tracked in practice, so it goes to `.ignore` when git sees one, and nowhere else.
 * A linked folder goes by its bare name, because `dir/` matches a folder and a worktree holds a link to it.
 */
export const ignoreLines = (
	listing: Listing,
	linked: readonly string[] = [],
): IgnoreLines => {
	const families: readonly Family[] = detectFamilies(listing.files);
	const heavy = unique(families.flatMap((family) => family.heavy));
	const bulky = unique(families.flatMap((family) => family.bulky ?? []));
	return {
		gitignore: unique([
			...GITIGNORE_FIXED,
			...linked,
			...heavy.filter(
				(pattern) =>
					!seen(pattern, listing.tracked) &&
					!linked.includes(pattern.slice(0, -1)),
			),
		]),
		ignore: [
			...heavy.filter((pattern) => seen(pattern, listing.tracked)),
			...bulky.filter((pattern) => seen(pattern, listing.files)),
		],
	};
};

export interface IgnoreEdit {
	readonly path: ".gitignore" | ".ignore";
	/** The file as read, or `undefined` when it does not exist. */
	readonly before: string | undefined;
	readonly after: string;
	/** The lines of the block, so the text can be rebuilt from the file as it is at the write. */
	readonly lines: readonly string[];
}

interface HeldIgnores {
	readonly gitignore?: string | undefined;
	readonly ignore?: string | undefined;
}

const editOf = (
	path: IgnoreEdit["path"],
	before: string | undefined,
	lines: readonly string[],
): IgnoreEdit[] => {
	const after = applyBlock(before, lines);
	return after === undefined || after === before
		? []
		: [{ path, before, after, lines }];
};

/** Only a file that changes is listed, so a rerun on a settled repo plans nothing. */
export const ignoreEdits = (
	listing: Listing,
	held: HeldIgnores,
	linked: readonly string[] = [],
): IgnoreEdit[] => {
	const lines = ignoreLines(listing, linked);
	return [
		...editOf(".gitignore", held.gitignore, lines.gitignore),
		...editOf(".ignore", held.ignore, lines.ignore),
	];
};

export const previewEdits = (edits: readonly IgnoreEdit[]): string =>
	edits.map((edit) => diffOf(edit.path, edit.before, edit.after)).join("\n");

/** The text to write, from the file as it is now; `undefined` when it needs no write. */
export const settle = (
	edit: IgnoreEdit,
	current: string | undefined,
): string | undefined => {
	const text = applyBlock(current, edit.lines);
	return text === current ? undefined : text;
};
